const headers = $json.headers || {};
const providedSecret = headers['x-fbc-webhook-secret'] || headers['X-FBC-Webhook-Secret'];
const expectedSecret = '***ROTATED-2026-08-06***'; // Hardcoded: this n8n Cloud plan has no Variables/env feature licensed.

// Keep failed authentication isolated from the request body so it cannot have side effects.
if (typeof providedSecret !== 'string' || typeof expectedSecret !== 'string' || providedSecret !== expectedSecret) {
  return [{ json: { authorized: false } }];
}

const body = $json.body && typeof $json.body === 'object' ? $json.body : {};
return [{
  json: {
    authorized: true,
    action: body.action,
    requestId: headers['x-fbc-request-id'] || headers['X-FBC-Request-Id'] || body.requestId,
    email: body.email,
    page: body.page,
    marketingConsent: body.marketingConsent === true,
    consentVersion: body.consentVersion || '',
    recipe: body.recipe || null,
    receivedAt: new Date().toISOString()
  }
}];

