const data = $input.first().json;
const websiteUrl = 'https://freezerbatchcocktails.com';
const unsubscribeUrl = 'https://freezerbatchcocktails.com/unsubscribe';
const html = `<!doctype html><html><body style="margin:0;background:#171411;color:#f4ede3;font-family:Arial,sans-serif;"><table role="presentation" width="100%"><tr><td align="center" style="padding:32px 16px;"><table role="presentation" width="600" style="max-width:600px;background:#241f1a;border:1px solid #3b342e;"><tr><td style="padding:36px;background:#0e0c0a;border-bottom:4px solid #d7b46a;"><p style="margin:0;color:#d7b46a;letter-spacing:2px;font-size:12px;">FREEZER BATCH COCKTAILS</p><h1 style="margin:8px 0 0;color:#f4ede3;">Welcome to the newsletter</h1></td></tr><tr><td style="padding:32px;color:#c8c0b7;line-height:1.6;"><p>Your recipe is on its way. You also opted into the newsletter, so you're subscribed — we'll send occasional freezer-batch recipes, ratios, and technique notes, a few times a month at most. Every email includes an unsubscribe link, so you can leave whenever you like.</p><p><a href="${websiteUrl}/cocktails" style="background:#d7b46a;color:#171411;padding:13px 20px;text-decoration:none;font-weight:bold;">Explore cocktails</a></p></td></tr><tr><td style="padding:22px 32px;background:#0e0c0a;color:#a69d93;font-size:12px;">Freezer Batch Cocktails · <a href="${unsubscribeUrl}" style="color:#d7b46a;">Unsubscribe</a></td></tr></table></td></tr></table></body></html>`;
const text = `FREEZER BATCH COCKTAILS\n\nYour recipe is on its way. You also opted into the newsletter, so you're subscribed — we'll send occasional freezer-batch recipes, ratios, and technique notes, a few times a month at most. Every email includes an unsubscribe link, so you can leave whenever you like.\n\nExplore cocktails: ${websiteUrl}/cocktails\nUnsubscribe: ${unsubscribeUrl}`;
return [{ json: { ...data, html, text, subject: 'Welcome to Freezer Batch Cocktails' } }];

const data = $input.first().json;
const recipe = data.recipe && typeof data.recipe === 'object' ? data.recipe : {};
const display = recipe.display && typeof recipe.display === 'object' ? recipe.display : {};
const plain = (value) => String(value ?? '').replace(/[\r\n]+/g, ' ').trim();
const bounded = (value, max = 160) => Array.from(plain(value)).slice(0, max).join('');
const escapeHtml = (value) => bounded(value).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\"/g, '&quot;').replace(/'/g, '&#39;');
const show = (value, fallback = '—') => escapeHtml(bounded(value) || fallback);
const slugLabel = (slug) => bounded(slug, 80).split('-').filter(Boolean).map((part) => part[0]?.toUpperCase() + part.slice(1)).join(' ');
const unit = recipe.unit === 'oz' || recipe.unit === 'ml' ? recipe.unit : 'ml';
const bottleFallback = Number.isInteger(recipe.bottleMl) ? `${recipe.bottleMl} ml` : '—';
const dilutionFallback = recipe.mode === 'custom' && Number.isFinite(recipe.dilutionPercent) ? `${recipe.dilutionPercent}%` : '—';
const recipeNamePlain = bounded(display.name) || (recipe.mode === 'preset' ? slugLabel(recipe.slug) : '') || (recipe.mode === 'custom' ? 'Custom Freezer Batch' : 'Freezer Batch');
const recipeName = escapeHtml(recipeNamePlain);
const presentationIngredients = Array.isArray(display.ingredients) ? display.ingredients : [];
const coreIngredients = recipe.mode === 'custom' && Array.isArray(recipe.ingredients) ? recipe.ingredients : [];
const ingredients = presentationIngredients.length ? presentationIngredients : coreIngredients.map((ingredient) => ({ name: ingredient?.name, amount: `${ingredient?.amount ?? ''} ${unit}`.trim() }));
const ingredientRows = ingredients.length ? ingredients.map((ingredient) => `<tr><td>${show(ingredient?.name, 'Ingredient')}</td><td>${show(ingredient?.amount)}</td></tr>`).join('') : `<tr><td colspan='2'>See the calculator for the complete ingredient list.</td></tr>`;
const textIngredients = ingredients.length ? ingredients.map((ingredient) => `- ${bounded(ingredient?.name) || 'Ingredient'}: ${bounded(ingredient?.amount) || '—'}`).join('\n') : '- See the calculator for the complete ingredient list.';
const abv = show(display.abv);
const servings = show(display.servings);
const bottleSize = show(display.bottleSize, bottleFallback);
const dilution = show(display.dilution, dilutionFallback);
const pourOff = show(display.pourOff, 'See calculator');
const waterToAdd = show(display.waterToAdd, 'See calculator');
